package server

// Authorization policies for the orgs routes. See route_auth_policy_test.go
// for the classes; routePolicyFile says which file a new route belongs in.
func init() {
	declareRoutePolicies(map[string]routePolicy{
		"GET /api/v1/slack/oauth/callback":                                                                handlerAuth("browser redirect from Slack; runs extractMiddleware and completes only when the browser session is the org admin sealed into the encrypted state parameter"),
		"GET /api/v1/orgs/{org}/slack/apps":                                                               object("authorizeOrgMember"),
		"GET /api/v1/orgs/{org}/slack/oauth/start":                                                        object("authorizeOrgOwner"),
		"GET /api/v1/orgs/{org}/slack/workspaces":                                                         object("authorizeOrgMember"),
		"POST /api/v1/orgs/{org}/slack/workspaces":                                                        object("authorizeOrgOwner"),
		"DELETE /api/v1/orgs/{org}/slack/workspaces/{id}":                                                 object("authorizeOrgOwner"),
		"GET /api/v1/orgs/{org}/settings":                                                                 object("authorizeOrgMember"),
		"PUT /api/v1/orgs/{org}/settings/{key}":                                                           object("authorizeOrgMember"),
		"DELETE /api/v1/orgs/{org}/settings/{key}":                                                        object("authorizeOrgMember"),
		"GET /api/v1/orgs/{org}/github/app-installation":                                                  object("authorizeOrgMember"),
		"POST /api/v1/orgs/{org}/github/app-manifest":                                                     object("authorizeOrgMember"),
		// The helix-org routes inside this prefix: helixOrgRoutePolicies.
		"ANY /api/v1/orgs/{org}/":                                                                         object("withHelixOrgIdentity"),
		"GET /api/v1/wallet":                                                                              object("authorizeOrgMember"),
		"POST /api/v1/subscription/new":                                                                   object("authorizeOrgOwner"),
		"POST /api/v1/subscription/manage":                                                                object("authorizeOrgOwner"),
		"POST /api/v1/top-ups/new":                                                                        object("authorizeOrgOwner"),
		"GET /api/v1/usage":                                                                               object("authorizeOrgMember"),
		"GET /api/v1/usage/org-summary":                                                                   object("authorizeOrgMember"),
		"GET /api/v1/quotas":                                                                              object("authorizeOrgMember"),
		"GET /api/v1/organizations":                                                                       user(),
		"POST /api/v1/organizations":                                                                      user(),
		"GET /api/v1/organizations/{id}":                                                                  object("authorizeOrgMember"),
		"PUT /api/v1/organizations/{id}":                                                                  object("authorizeOrgOwner"),
		"DELETE /api/v1/organizations/{id}":                                                               object("authorizeOrgOwner"),
		"GET /api/v1/organizations/{id}/members":                                                          object("authorizeOrgMember"),
		"POST /api/v1/organizations/{id}/members":                                                         object("authorizeOrgOwner"),
		"DELETE /api/v1/organizations/{id}/members/{user_id}":                                             object("authorizeOrgOwner"),
		"PUT /api/v1/organizations/{id}/members/{user_id}":                                                object("authorizeOrgOwner"),
		"GET /api/v1/organizations/{id}/invitations":                                                      object("authorizeOrgMember"),
		"POST /api/v1/organizations/{id}/invitations":                                                     object("authorizeOrgOwner"),
		"DELETE /api/v1/organizations/{id}/invitations/{invitation_id}":                                   object("authorizeOrgOwner"),
		"POST /api/v1/organizations/{id}/invitations/{invitation_id}/link":                                object("authorizeOrgOwner"),
		"GET /api/v1/organizations/{id}/users/lookup":                                                     object("authorizeOrgOwner"),
		"GET /api/v1/organizations/{id}/roles":                                                            object("authorizeOrgMember"),
		"GET /api/v1/organizations/{id}/guidelines-history":                                               object("authorizeOrgMember"),
		"GET /api/v1/organizations/{id}/api_keys":                                                         object("authorizeOrgMember"),
		"POST /api/v1/organizations/{id}/api_keys":                                                        object("authorizeOrgMember"),
		"DELETE /api/v1/organizations/{id}/api_keys/{key}":                                                object("authorizeOrgMember"),
		"GET /api/v1/organizations/{id}/webhook-endpoints":                                                object("authorizeWebhookOwner"),
		"POST /api/v1/organizations/{id}/webhook-endpoints":                                               object("authorizeWebhookOwner"),
		"PUT /api/v1/organizations/{id}/webhook-endpoints/{endpoint_id}":                                  object("authorizeWebhookOwner"),
		"DELETE /api/v1/organizations/{id}/webhook-endpoints/{endpoint_id}":                               object("authorizeWebhookOwner"),
		"POST /api/v1/organizations/{id}/webhook-endpoints/{endpoint_id}/rotate-secret":                   object("authorizeWebhookOwner"),
		"GET /api/v1/organizations/{id}/webhook-endpoints/{endpoint_id}/deliveries":                       object("authorizeWebhookOwner"),
		"POST /api/v1/organizations/{id}/webhook-endpoints/{endpoint_id}/deliveries/{delivery_id}/replay": object("authorizeWebhookOwner"),
		"GET /api/v1/organizations/{org_id}/code-agent-harnesses":                                         object("authorizeOrgMember"),
		"PUT /api/v1/organizations/{org_id}/code-agent-harnesses":                                         object("authorizeOrgOwner"),
		"GET /api/v1/organizations/{org_id}/sandboxes":                                                    object("authorizeOrgMember"),
		"POST /api/v1/organizations/{org_id}/sandboxes":                                                   object("authorizeOrgMember"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}":                                               object("loadAuthorizedSandbox"),
		"PATCH /api/v1/organizations/{org_id}/sandboxes/{id}":                                             object("loadAuthorizedSandbox"),
		"DELETE /api/v1/organizations/{org_id}/sandboxes/{id}":                                            object("loadAuthorizedSandbox"),
		"POST /api/v1/organizations/{org_id}/sandboxes/{id}/commands":                                     object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/commands":                                      object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/commands/{cmd_id}":                             object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/commands/{cmd_id}/logs":                        object("loadAuthorizedSandbox"),
		"POST /api/v1/organizations/{org_id}/sandboxes/{id}/commands/{cmd_id}/kill":                       object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/files":                                         object("loadAuthorizedSandbox"),
		"PUT /api/v1/organizations/{org_id}/sandboxes/{id}/files":                                         object("loadAuthorizedSandbox"),
		"DELETE /api/v1/organizations/{org_id}/sandboxes/{id}/files":                                      object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/files/list":                                    object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/terminal":                                      object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/terminal/sessions":                             object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/screenshot":                                    object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/sandboxes/{id}/billing":                                       object("loadAuthorizedSandbox"),
		"GET /api/v1/organizations/{org_id}/websearch/usage":                                              object("authorizeOrgMember"),
		"GET /api/v1/organizations/{org_id}/websearch/requests":                                           object("authorizeOrgMember"),
		"GET /api/v1/organizations/{id}/teams":                                                            object("authorizeOrgMember"),
		"POST /api/v1/organizations/{id}/teams":                                                           object("authorizeOrgOwner"),
		"PUT /api/v1/organizations/{id}/teams/{team_id}":                                                  object("authorizeOrgOwner"),
		"DELETE /api/v1/organizations/{id}/teams/{team_id}":                                               object("authorizeOrgOwner"),
		"GET /api/v1/organizations/{id}/teams/{team_id}/members":                                          object("authorizeOrgMember"),
		"POST /api/v1/organizations/{id}/teams/{team_id}/members":                                         object("authorizeOrgMember", "authorizeOrgOwner"),
		"DELETE /api/v1/organizations/{id}/teams/{team_id}/members/{user_id}":                             object("authorizeOrgOwner"),
	})
}
